CREATE TABLE "NewsCategory" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "NewsCategory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "News" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "subtitle" TEXT NOT NULL DEFAULT '', "summary" TEXT NOT NULL DEFAULT '', "content" TEXT NOT NULL, "coverUrl" TEXT, "published" BOOLEAN NOT NULL DEFAULT false, "featured" BOOLEAN NOT NULL DEFAULT false, "publishedAt" TIMESTAMP(3), "authorId" TEXT NOT NULL, "categoryId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "News_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Event" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "location" TEXT NOT NULL DEFAULT '', "coverUrl" TEXT, "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3), "status" TEXT NOT NULL DEFAULT 'AGENDADO', "published" BOOLEAN NOT NULL DEFAULT false, "featured" BOOLEAN NOT NULL DEFAULT false, "authorId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Event_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Album" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "coverUrl" TEXT, "published" BOOLEAN NOT NULL DEFAULT false, "authorId" TEXT NOT NULL, "newsId" TEXT, "eventId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Album_pkey" PRIMARY KEY ("id"));
ALTER TABLE "Album" ADD COLUMN "slug" TEXT NOT NULL DEFAULT '';
ALTER TABLE "News" ADD COLUMN "coverPublicId" TEXT;
ALTER TABLE "Event" ADD COLUMN "coverPublicId" TEXT;
ALTER TABLE "Album" ADD COLUMN "coverPublicId" TEXT;
CREATE UNIQUE INDEX "Album_slug_key" ON "Album"("slug");
CREATE TABLE "Photo" ("id" TEXT NOT NULL, "url" TEXT NOT NULL, "publicId" TEXT, "alt" TEXT NOT NULL DEFAULT '', "sortOrder" INTEGER NOT NULL DEFAULT 0, "newsId" TEXT, "eventId" TEXT, "albumId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Photo_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AdminPasswordOtp" ("id" TEXT NOT NULL, "adminId" TEXT NOT NULL, "codeHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AdminPasswordOtp_pkey" PRIMARY KEY ("id"));
ALTER TABLE "AdminUser" ADD COLUMN "permissions" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "isSuperAdmin" BOOLEAN NOT NULL DEFAULT false;
CREATE UNIQUE INDEX "NewsCategory_name_key" ON "NewsCategory"("name"); CREATE UNIQUE INDEX "NewsCategory_slug_key" ON "NewsCategory"("slug"); CREATE UNIQUE INDEX "News_slug_key" ON "News"("slug"); CREATE INDEX "News_published_publishedAt_idx" ON "News"("published", "publishedAt"); CREATE UNIQUE INDEX "Event_slug_key" ON "Event"("slug"); CREATE INDEX "Event_published_startsAt_idx" ON "Event"("published", "startsAt"); CREATE INDEX "Photo_albumId_sortOrder_idx" ON "Photo"("albumId", "sortOrder");
ALTER TABLE "News" ADD CONSTRAINT "News_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "AdminUser"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "News" ADD CONSTRAINT "News_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "NewsCategory"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Event" ADD CONSTRAINT "Event_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "AdminUser"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Album" ADD CONSTRAINT "Album_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "AdminUser"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Album" ADD CONSTRAINT "Album_newsId_fkey" FOREIGN KEY ("newsId") REFERENCES "News"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Album" ADD CONSTRAINT "Album_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Photo" ADD CONSTRAINT "Photo_newsId_fkey" FOREIGN KEY ("newsId") REFERENCES "News"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Photo" ADD CONSTRAINT "Photo_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Photo" ADD CONSTRAINT "Photo_albumId_fkey" FOREIGN KEY ("albumId") REFERENCES "Album"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AdminPasswordOtp" ADD CONSTRAINT "AdminPasswordOtp_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "AdminUser"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE INDEX "AdminPasswordOtp_adminId_expiresAt_idx" ON "AdminPasswordOtp"("adminId", "expiresAt");
ALTER TABLE "AdminUser" ADD COLUMN "displayName" TEXT NOT NULL DEFAULT '', ADD COLUMN "phone" TEXT, ADD COLUMN "profilePhotoUrl" TEXT;
ALTER TABLE "AuditLog" ADD COLUMN "module" TEXT NOT NULL DEFAULT 'system', ADD COLUMN "metadata" JSONB;
CREATE TYPE "ContactMessageStatus" AS ENUM ('NAO_LIDA','LIDA','EM_TRATAMENTO','RESPONDIDA','ARQUIVADA');
CREATE TABLE "ContactMessage" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"subject" TEXT NOT NULL,"category" TEXT NOT NULL,"body" TEXT NOT NULL,"status" "ContactMessageStatus" NOT NULL DEFAULT 'NAO_LIDA',"assignedAdminId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ContactMessage_pkey" PRIMARY KEY("id"));
CREATE TABLE "MessageReply" ("id" TEXT NOT NULL,"messageId" TEXT NOT NULL,"adminId" TEXT NOT NULL,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MessageReply_pkey" PRIMARY KEY("id"));
