ALTER TABLE "ContactMessage" ADD CONSTRAINT "ContactMessage_assignedAdminId_fkey" FOREIGN KEY("assignedAdminId") REFERENCES "AdminUser"("id") ON DELETE SET NULL ON UPDATE CASCADE;
